-- PT112-S4-Q24. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT112-S4-Q24$batch11$ AND q.stimulus=$batch11$Telephone companies are promoting “voice mail” as an alternative to the answering machine. By recording messages from callers when a subscriber does not have access to his or her telephone, voice mail provides a service similar to that of an answering machine. The companies promoting this service argue that it will soon make answering machines obsolete, since it is much more convenient, more flexible, and less expensive than an answering machine.$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most calls into question the argument made by the companies promoting voice mail?$batch11$ AND q.correct_choice=$batch11$D$batch11$) THEN RAISE EXCEPTION 'Question changed: PT112-S4-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanation_steps s WHERE s.explanation_id=$batch11$b0f4e85c-c551-492c-b0be-51f1ce1b72a2$batch11$) <> 0 OR (SELECT COUNT(*) FROM lr_explanation_choice_notes n WHERE n.explanation_id=$batch11$b0f4e85c-c551-492c-b0be-51f1ce1b72a2$batch11$) <> 5 THEN RAISE EXCEPTION 'Explanation changed: PT112-S4-Q24'; END IF; END $guard$;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$Voice mail will soon make answering machines obsolete.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Voice mail does the same job as an answering machine and is more convenient, more flexible, and cheaper.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The companies only list voice mail's advantages. If answering machines do something valuable that voice mail can't, some people will keep them, and they won't become obsolete.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Find an advantage answering machines have over voice mail.$batch11$)) v(position,label,body) WHERE e.id=$batch11$b0f4e85c-c551-492c-b0be-51f1ce1b72a2$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
COMMIT;
